import { useState } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { GAME_CONFIG } from "@/lib/constants";
import { useSettings } from "@/lib/stores/useSettings";
import { CollectibleSparkles } from "./ParticleEffects";

export type CollectibleType = "arequipe" | "nitro" | "shield";

interface Collectible {
  id: number;
  type: CollectibleType;
  position: THREE.Vector3;
  rotation: number;
}

interface CollectiblesProps {
  carPositionRef: React.MutableRefObject<THREE.Vector3>;
  onCollect: (collectible: Collectible) => void;
}

export function Collectibles({ carPositionRef, onCollect }: CollectiblesProps) {
  const [collectibles, setCollectibles] = useState<Collectible[]>([]);
  const [nextCollectibleId, setNextCollectibleId] = useState(0);
  const [lastSpawnZ, setLastSpawnZ] = useState(0);
  const showPhotoMode = useSettings((state) => state.showPhotoMode);

  useFrame((state, delta) => {
    if (showPhotoMode) return;
    let newCollectibles = [...collectibles];
    let updatedLastSpawnZ = lastSpawnZ;
    let updatedNextId = nextCollectibleId;

    const distance = carPositionRef.current.z;
    const baseSpawnChance = 0.3;
    const difficultyFactor = Math.min(distance / 5000, 0.6);
    const adjustedSpawnChance = baseSpawnChance * (1 - difficultyFactor);

    if (carPositionRef.current.z > lastSpawnZ + 20) {
      if (Math.random() < adjustedSpawnChance) {
        const laneOffset = (Math.random() - 0.5) * (GAME_CONFIG.LANE_WIDTH - 3);

        const shieldChance = Math.max(0.15 - difficultyFactor * 0.1, 0.05);
        const nitroChance = Math.max(0.15 - difficultyFactor * 0.05, 0.08);

        const rand = Math.random();
        let type: CollectibleType = "arequipe";
        if (rand < 1 - shieldChance - nitroChance) {
          type = "arequipe";
        } else if (rand < 1 - shieldChance) {
          type = "nitro";
        } else {
          type = "shield";
        }

        newCollectibles.push({
          id: updatedNextId,
          type,
          position: new THREE.Vector3(laneOffset, 0.5, carPositionRef.current.z + 60),
          rotation: Math.random() * Math.PI * 2
        });

        updatedNextId++;
      }
      updatedLastSpawnZ = carPositionRef.current.z;
    }

    newCollectibles = newCollectibles.filter((collectible) => {
      const distanceToCar = new THREE.Vector2(
        carPositionRef.current.x - collectible.position.x,
        carPositionRef.current.z - collectible.position.z
      ).length();

      if (distanceToCar < 1.2) {
        onCollect(collectible);
        return false;
      }

      return collectible.position.z > carPositionRef.current.z - 20;
    });

    newCollectibles.forEach((collectible) => {
      collectible.rotation += delta * 2;
    });

    if (newCollectibles.length !== collectibles.length || updatedLastSpawnZ !== lastSpawnZ) {
      setCollectibles(newCollectibles);
      setLastSpawnZ(updatedLastSpawnZ);
      setNextCollectibleId(updatedNextId);
    }
  });

  return (
    <group>
      {collectibles.map((collectible) => (
        <group key={collectible.id}>
          <CollectibleModel collectible={collectible} />
          <CollectibleSparkles position={collectible.position} />
        </group>
      ))}
    </group>
  );
}

function CollectibleModel({ collectible }: { collectible: Collectible }) {
  if (collectible.type === "arequipe") {
    return <ArequipeJar collectible={collectible} />;
  } else if (collectible.type === "nitro") {
    return <NitroPowerUp collectible={collectible} />;
  } else {
    return <ShieldPowerUp collectible={collectible} />;
  }
}

function ArequipeJar({ collectible }: { collectible: Collectible }) {
  const position: [number, number, number] = [
    collectible.position.x,
    collectible.position.y,
    collectible.position.z
  ];

  return (
    <group position={position} rotation={[0, collectible.rotation, 0]}>
      <mesh castShadow>
        <cylinderGeometry args={[0.25, 0.3, 0.4, 16]} />
        <meshStandardMaterial 
          color="#D4A574"
          roughness={0.3}
          metalness={0.2}
        />
      </mesh>

      <mesh position={[0, 0.25, 0]} castShadow>
        <cylinderGeometry args={[0.28, 0.28, 0.1, 16]} />
        <meshStandardMaterial 
          color="#8B4513"
          roughness={0.5}
        />
      </mesh>

      <mesh position={[0, 0, 0]}>
        <sphereGeometry args={[0.5, 16, 16]} />
        <meshStandardMaterial 
          color="#FDC6B5"
          transparent
          opacity={0.3}
          emissive="#FDC6B5"
          emissiveIntensity={0.5}
        />
      </mesh>
    </group>
  );
}

function NitroPowerUp({ collectible }: { collectible: Collectible }) {
  const position: [number, number, number] = [
    collectible.position.x,
    collectible.position.y,
    collectible.position.z
  ];

  return (
    <group position={position} rotation={[0, collectible.rotation, 0]}>
      <mesh castShadow>
        <cylinderGeometry args={[0.2, 0.2, 0.6, 8]} />
        <meshStandardMaterial 
          color="#ff3333"
          emissive="#ff0000"
          emissiveIntensity={0.5}
          metalness={0.6}
        />
      </mesh>

      <mesh position={[0, 0.4, 0]}>
        <coneGeometry args={[0.22, 0.2, 8]} />
        <meshStandardMaterial 
          color="#ffaa00"
          emissive="#ff5500"
          emissiveIntensity={0.7}
        />
      </mesh>

      <mesh position={[0, 0, 0]}>
        <sphereGeometry args={[0.6, 16, 16]} />
        <meshStandardMaterial 
          color="#ff6633"
          transparent
          opacity={0.2}
          emissive="#ff3300"
          emissiveIntensity={0.4}
        />
      </mesh>
    </group>
  );
}

function ShieldPowerUp({ collectible }: { collectible: Collectible }) {
  const position: [number, number, number] = [
    collectible.position.x,
    collectible.position.y,
    collectible.position.z
  ];

  return (
    <group position={position} rotation={[0, collectible.rotation, 0]}>
      <mesh castShadow>
        <octahedronGeometry args={[0.3, 0]} />
        <meshStandardMaterial 
          color="#24A0CE"
          emissive="#24A0CE"
          emissiveIntensity={0.6}
          metalness={0.8}
        />
      </mesh>

      <mesh position={[0, 0, 0]}>
        <sphereGeometry args={[0.55, 16, 16]} />
        <meshStandardMaterial 
          color="#24A0CE"
          transparent
          opacity={0.25}
          emissive="#24A0CE"
          emissiveIntensity={0.3}
        />
      </mesh>
    </group>
  );
}

client/src/lib/stores/useRally.tsx.content:
import { create } from "zustand";
import { subscribeWithSelector } from "zustand/middleware";
import { audioManager } from "@/lib/audio";

export type RallyPhase = "menu" | "loading" | "tutorial" | "playing" | "paused" | "gameover";

interface RallyState {
  phase: RallyPhase;
  distance: number;
  speed: number;
  highScore: number;
  currentScore: number;
  collectiblesCount: number;
  startTime: number;
  playerName: string;
  scoreSubmitted: boolean;
  countdown: number;
  isCountingDown: boolean;
  tutorialReturnPhase: RallyPhase | null;

  start: () => void;
  pause: () => void;
  resume: () => void;
  gameOver: () => void;
  restart: () => void;
  updateDistance: (distance: number) => void;
  updateSpeed: (speed: number) => void;
  addCollectible: () => void;
  loadHighScore: () => void;
  saveHighScore: () => void;
  setPlayerName: (name: string) => void;
  loadPlayerName: () => void;
  setCountdown: (count: number) => void;
  startCountdown: () => void;
  startLoading: () => void;
  finishLoading: () => void;
  showTutorial: () => void;
  closeTutorial: () => void;
}

export const useRally = create<RallyState>()(
  subscribeWithSelector((set, get) => ({
    phase: "menu",
    distance: 0,
    speed: 0,
    highScore: 0,
    currentScore: 0,
    collectiblesCount: 0,
    startTime: 0,
    playerName: "",
    scoreSubmitted: false,
    countdown: 3,
    isCountingDown: false,
    tutorialReturnPhase: null,

    startLoading: () => {
      audioManager.stopBackgroundMusic();
      set({ 
        phase: "loading",
        distance: 0,
        speed: 0,
        currentScore: 0,
        collectiblesCount: 0,
        isCountingDown: false,
        countdown: 3
      });
    },

    finishLoading: () => {
      const tutorialShown = sessionStorage.getItem("tutorialShown");
      console.log("[finishLoading] tutorialShown in sessionStorage:", tutorialShown);
      if (!tutorialShown) {
        console.log("[finishLoading] First time - showing tutorial");
        set({ phase: "tutorial", tutorialReturnPhase: "loading" });
      } else {
        console.log("[finishLoading] Tutorial already shown - starting game");
        const now = Date.now();
        set({ 
          phase: "playing",
          isCountingDown: true, 
          countdown: 3,
          startTime: now
        });
      }
    },

    showTutorial: () => {
      const currentPhase = get().phase;
      set({ phase: "tutorial", tutorialReturnPhase: currentPhase });
    },

    closeTutorial: () => {
      const state = get();
      const returnPhase = state.tutorialReturnPhase;

      if (returnPhase === "menu") {
        set({ phase: "menu", tutorialReturnPhase: null });
      } else if (returnPhase === "paused") {
        set({ phase: "paused", tutorialReturnPhase: null });
      } else if (returnPhase === "loading") {
        const now = Date.now();
        set({ 
          phase: "playing",
          isCountingDown: true, 
          countdown: 3,
          startTime: now,
          tutorialReturnPhase: null
        });
      } else {
        set({ phase: "menu", tutorialReturnPhase: null });
      }
    },

    startCountdown: () => {
      const now = Date.now();
      audioManager.stopBackgroundMusic();
      set({ 
        phase: "playing",
        isCountingDown: true, 
        countdown: 3,
        distance: 0,
        speed: 0,
        currentScore: 0,
        collectiblesCount: 0,
        startTime: now
      });
    },

    setCountdown: (count: number) => {
      set({ countdown: count });
      if (count === 0) {
        setTimeout(() => {
          set({ isCountingDown: false });
          get().start();
        }, 1000);
      }
    },

    start: () => {
      const now = Date.now();
      set({
        phase: "playing",
        distance: 0,
        speed: 0,
        currentScore: 0,
        collectiblesCount: 0,
        startTime: now,
        isCountingDown: false
      });
    },

    pause: () => {
      set((state) => state.phase === "playing" ? { phase: "paused" } : {});
    },

    resume: () => {
      set((state) => state.phase === "paused" ? { phase: "playing" } : {});
    },

    gameOver: () => {
      const state = get();
      if (state.phase === "playing") {
        const finalScore = Math.floor(state.distance) + (state.collectiblesCount * 50);
        const newHighScore = Math.max(finalScore, state.highScore);

        if (newHighScore > state.highScore) {
          localStorage.setItem("dreamNexusRallyHighScore", String(newHighScore));
        }

        audioManager.stopEngineSound();

        set({ phase: "gameover", currentScore: finalScore, highScore: newHighScore, scoreSubmitted: false });

        if (state.playerName && finalScore > 0) {
          fetch("/api/leaderboard", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              playerName: state.playerName,
              score: finalScore,
              distance: Math.floor(state.distance),
            }),
          })
            .then(response => {
              if (response.ok) {
                return response.json();
              }
              throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            })
            .then(data => {
              console.log("Score submitted:", data);
              set({ scoreSubmitted: true });
            })
            .catch(err => {
              console.error("Failed to submit score:", err);
            });
        }
      }
    },

    restart: () => {
      audioManager.playBackgroundMusic();
      set({ phase: "menu", distance: 0, speed: 0, currentScore: 0, collectiblesCount: 0, scoreSubmitted: false });
    },

    updateDistance: (distance: number) => {
      set({ distance });
    },

    updateSpeed: (speed: number) => {
      set({ speed });
    },

    addCollectible: () => {
      set((state) => ({
        collectiblesCount: state.collectiblesCount + 1,
        currentScore: state.currentScore + 50
      }));
    },

    loadHighScore: () => {
      const saved = localStorage.getItem("dreamNexusRallyHighScore");
      const highScore = saved ? parseInt(saved, 10) : 0;
      set({ highScore });
    },

    saveHighScore: () => {
      const { currentScore, highScore } = get();
      const newHighScore = Math.max(currentScore, highScore);
      localStorage.setItem("dreamNexusRallyHighScore", String(newHighScore));
      set({ highScore: newHighScore });
    },

    setPlayerName: (name: string) => {
      set({ playerName: name });
      localStorage.setItem("dreamNexusRallyPlayerName", name);
    },

    loadPlayerName: () => {
      const saved = localStorage.getItem("dreamNexusRallyPlayerName");
      if (saved) {
        set({ playerName: saved });
      }
    }
  }))
);

