          position: "absolute",
          inset: 0,
          zIndex: 10,
          pointerEvents: "none",
        }}
      >
        {isMobile ? (
          <>
            {/* Mobile Layout */}
            {/* Title - Top */}
            <div style={{ 
              position: "absolute", 
              top: "10px", 
              left: "50%", 
              transform: "translateX(-50%)", 
              textAlign: "center",
              pointerEvents: "none",
              width: "100%",
              padding: "0 10px",
            }}>
              <img
                src="/dream-nexus-logo.png"
