import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { useBiome } from "@/lib/stores/useBiome";

interface ParticleData {
  position: THREE.Vector3;
  velocity: THREE.Vector3;
  life: number;
  maxLife: number;
}

export function AtmosphericParticles({ carPositionRef }: { carPositionRef: React.MutableRefObject<THREE.Vector3> }) {
  const pointsRef = useRef<THREE.Points>(null);
  const { currentBiome } = useBiome();

  const particleCount = 150;
  const particles = useRef<ParticleData[]>([]);

  const { geometry, positions, colors, sizes } = useMemo(() => {
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(particleCount * 3);
    const col = new Float32Array(particleCount * 3);
    const siz = new Float32Array(particleCount);

    particles.current = [];
    for (let i = 0; i < particleCount; i++) {
      particles.current.push({
        position: new THREE.Vector3(
          (Math.random() - 0.5) * 40,
          Math.random() * 15,
          (Math.random() - 0.5) * 60
        ),
        velocity: new THREE.Vector3(
          (Math.random() - 0.5) * 0.02,
          -0.01 - Math.random() * 0.02,
          -0.05 - Math.random() * 0.1
        ),
        life: Math.random(),
        maxLife: 1,
      });
    }

    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(siz, 1));

    return { geometry: geo, positions: pos, colors: col, sizes: siz };
  }, []);

  const particleColor = useMemo(() => {
    switch (currentBiome) {
      case "coffee_hills":
        return new THREE.Color(0x8B4513);
      case "andes_highland":
        return new THREE.Color(0xE8F4F8);
      case "pueblo":
        return new THREE.Color(0xFFE5CC);
      default:
        return new THREE.Color(0xFFFFFF);
    }
  }, [currentBiome]);

  useFrame((_, delta) => {
    if (!pointsRef.current) return;

    const carPos = carPositionRef.current;

    for (let i = 0; i < particleCount; i++) {
      const particle = particles.current[i];

      particle.position.add(particle.velocity);
      particle.life -= delta * 0.3;

      if (particle.life <= 0 || particle.position.y < -1) {
        particle.position.set(
          (Math.random() - 0.5) * 40,
          12 + Math.random() * 5,
          carPos.z + 20 + Math.random() * 40
        );
        particle.life = 1;

        if (currentBiome === "coffee_hills") {
          particle.velocity.set(
            (Math.random() - 0.5) * 0.03,
            -0.015,
            -0.08
          );
        } else if (currentBiome === "andes_highland") {
          particle.velocity.set(
            (Math.random() - 0.5) * 0.01,
            -0.02,
            -0.06
          );
        } else {
          particle.velocity.set(
            (Math.random() - 0.5) * 0.02,
            -0.01,
            -0.07
          );
        }
      }

      const idx = i * 3;
      positions[idx] = particle.position.x;
      positions[idx + 1] = particle.position.y;
      positions[idx + 2] = particle.position.z;

      const alpha = particle.life;
      colors[idx] = particleColor.r * alpha;
      colors[idx + 1] = particleColor.g * alpha;
      colors[idx + 2] = particleColor.b * alpha;

      sizes[i] = currentBiome === "coffee_hills" ? 0.15 : 0.25;
    }

    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
    geometry.attributes.size.needsUpdate = true;
  });

  return (
    <points ref={pointsRef}>
      <primitive object={geometry} attach="geometry" />
      <pointsMaterial
        size={0.2}
        sizeAttenuation
        vertexColors
        transparent
        opacity={0.6}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  );
}

client/src/components/ui/TitleScene3D.ts.content:
import { Canvas } from "@react-three/fiber";
import { useGLTF, PerspectiveCamera, Environment as DreiEnvironment, Float, Html } from "@react-three/drei";
import { Suspense, useRef, useMemo, useState, useEffect } from "react";
import * as THREE from "three";
import { useFrame } from "@react-three/fiber";

function LoadingFallback() {
  return (
    <Html center>
      <div style={{ color: "#24A0CE", fontFamily: "monospace", fontSize: "18px" }}>
        Loading 3D Scene...
      </div>
    </Html>
  );
}

function PixelBunny() {
  const { scene } = useGLTF("/pixel-bunny-3d.glb");
  const bunnyRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (bunnyRef.current) {
      bunnyRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
      bunnyRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.8) * 0.05;
    }
  });

  return (
    <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.3}>
      <primitive ref={bunnyRef} object={scene.clone()} scale={1.5} position={[0, 0, 0]} />
    </Float>
  );
}

function RallyCar() {
  const { scene } = useGLTF("/models/rally-car.glb");
  const carRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (carRef.current) {
      carRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.6 + 1) * 0.03;
    }
  });

  return (
    <Float speed={1.2} rotationIntensity={0.1} floatIntensity={0.2}>
      <primitive ref={carRef} object={scene.clone()} scale={0.8} position={[2, -0.3, 0.5]} rotation={[0, -0.5, 0]} />
    </Float>
  );
}

function CoffeeParticles({ isMobile }: { isMobile: boolean }) {
  const count = isMobile ? 15 : 30;
  const meshRef = useRef<THREE.InstancedMesh>(null);

  const positions = useMemo(() => {
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 8;
      pos[i * 3 + 1] = (Math.random() - 0.5) * 6;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 4;
    }
    return pos;
  }, [count]);

  useFrame((state) => {
    if (meshRef.current) {
      for (let i = 0; i < count; i++) {
        const i3 = i * 3;
        const matrix = new THREE.Matrix4();
        const y = positions[i3 + 1] + state.clock.elapsedTime * 0.1;
        const wrappedY = ((y + 3) % 6) - 3;

        matrix.setPosition(
          positions[i3] + Math.sin(state.clock.elapsedTime * 0.5 + i) * 0.2,
          wrappedY,
          positions[i3 + 2]
        );
        matrix.scale(new THREE.Vector3(0.05, 0.05, 0.05));
        meshRef.current.setMatrixAt(i, matrix);
      }
      meshRef.current.instanceMatrix.needsUpdate = true;
    }
  });

  return (
    <instancedMesh ref={meshRef} args={[undefined, undefined, count]}>
      <sphereGeometry args={[1, 8, 8]} />
      <meshStandardMaterial color="#8B4513" emissive="#654321" emissiveIntensity={0.3} />
    </instancedMesh>
  );
}

function AutoRotateCamera() {
  const cameraRef = useRef<THREE.PerspectiveCamera>(null);

  useFrame((state) => {
    if (cameraRef.current) {
      const radius = 6;
      const x = Math.sin(state.clock.elapsedTime * 0.15) * radius;
      const z = Math.cos(state.clock.elapsedTime * 0.15) * radius;
      cameraRef.current.position.set(x, 2, z);
      cameraRef.current.lookAt(0, 0.5, 0);
    }
  });

  return <PerspectiveCamera ref={cameraRef} makeDefault position={[5, 2, 5]} fov={50} />;
}

function SceneLighting() {
  return (
    <>
      <ambientLight intensity={0.4} />
      <spotLight position={[5, 8, 5]} intensity={1.2} angle={0.4} penumbra={0.5} castShadow color="#24A0CE" />
      <spotLight position={[-5, 5, -5]} intensity={0.8} angle={0.3} penumbra={0.6} color="#FDC6B5" />
      <pointLight position={[0, 1, 2]} intensity={0.5} color="#24A0CE" />
    </>
  );
}

export function TitleScene3D() {
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener("resize", checkMobile);
    return () => window.removeEventListener("resize", checkMobile);
  }, []);

  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 1 }}>
      <Canvas 
        shadows 
        dpr={isMobile ? [1, 1.5] : [1, 2]}
        performance={{ min: 0.5 }}
      >
        <Suspense fallback={<LoadingFallback />}>
          <AutoRotateCamera />
          <SceneLighting />

          <PixelBunny />
          <RallyCar />
          <CoffeeParticles isMobile={isMobile} />

          <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.5, 0]} receiveShadow>
            <planeGeometry args={[20, 20]} />
            <meshStandardMaterial color="#0E1B24" roughness={0.8} />
          </mesh>

          <DreiEnvironment preset="sunset" />
          <fog attach="fog" args={["#0E1B24", 5, 15]} />
        </Suspense>
      </Canvas>
    </div>
  );
}

client/src/components/game/Sky.tsx.content:
import { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { useBiome } from "@/lib/stores/useBiome";

interface CloudData {
  position: THREE.Vector3;
  scale: number;
  speed: number;
  offset: number;
}

export function Sky() {
  const skyRef = useRef<THREE.Mesh>(null);
  const cloudsGroupRef = useRef<THREE.Group>(null);
  const { currentBiome } = useBiome();

  const clouds = useMemo<CloudData[]>(() => {
    const cloudArray: CloudData[] = [];
    for (let i = 0; i < 20; i++) {
      cloudArray.push({
        position: new THREE.Vector3(
          (Math.random() - 0.5) * 200,
          20 + Math.random() * 15,
          -50 - Math.random() * 150
        ),
        scale: 3 + Math.random() * 4,
        speed: 0.3 + Math.random() * 0.5,
        offset: Math.random() * Math.PI * 2,
      });
    }
    return cloudArray;
  }, []);

  const skyColors = useMemo(() => {
    switch (currentBiome) {
      case "coffee_hills":
        return {
          top: new THREE.Color(0x87CEEB),
          bottom: new THREE.Color(0xE8D4A0),
        };
      case "andes_highland":
        return {
          top: new THREE.Color(0x6BA3D8),
          bottom: new THREE.Color(0xB8C5D6),
        };
      case "pueblo":
        return {
          top: new THREE.Color(0xFFAA66),
          bottom: new THREE.Color(0xFFE5CC),
        };
      default:
        return {
          top: new THREE.Color(0x87CEEB),
          bottom: new THREE.Color(0xFFE5CC),
        };
    }
  }, [currentBiome]);

  const skyGeometry = useMemo(() => {
    const geometry = new THREE.SphereGeometry(300, 32, 32);
    const colors = [];
    const positions = geometry.attributes.position;

    for (let i = 0; i < positions.count; i++) {
      const y = positions.getY(i);
      const t = (y + 300) / 600;
      const color = new THREE.Color();
      color.lerpColors(skyColors.bottom, skyColors.top, t);
      colors.push(color.r, color.g, color.b);
    }

    geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    return geometry;
  }, [skyColors]);

  useFrame((state) => {
    if (!cloudsGroupRef.current) return;

    cloudsGroupRef.current.children.forEach((cloud, i) => {
      const cloudData = clouds[i];
      cloud.position.z += cloudData.speed * 0.05;

      if (cloud.position.z > 100) {
        cloud.position.z = -200;
        cloud.position.x = (Math.random() - 0.5) * 200;
      }

      cloud.position.y += Math.sin(state.clock.elapsedTime * 0.5 + cloudData.offset) * 0.002;
    });
  });

  return (
    <group>
      <mesh ref={skyRef} scale={[-1, 1, 1]}>
        <primitive object={skyGeometry} />
        <meshBasicMaterial vertexColors side={THREE.BackSide} />
      </mesh>

      <group ref={cloudsGroupRef}>
        {clouds.map((cloud, i) => (
          <Cloud key={i} cloudData={cloud} biome={currentBiome} />
        ))}
      </group>
    </group>
  );
}

function Cloud({ cloudData, biome }: { cloudData: CloudData; biome: string }) {
  const cloudRef = useRef<THREE.Mesh>(null);

  const cloudColor = useMemo(() => {
    switch (biome) {
      case "coffee_hills":
        return new THREE.Color(0xFFFFFF);
      case "andes_highland":
        return new THREE.Color(0xE8F4F8);
      case "pueblo":
        return new THREE.Color(0xFFE8D0);
      default:
        return new THREE.Color(0xFFFFFF);
    }
  }, [biome]);

  useFrame(() => {
    if (cloudRef.current) {
      cloudRef.current.rotation.y += 0.001;
    }
  });

  return (
    <mesh ref={cloudRef} position={cloudData.position} scale={cloudData.scale}>
      <sphereGeometry args={[1, 8, 8]} />
      <meshBasicMaterial
        color={cloudColor}
        transparent
        opacity={0.6}
        depthWrite={false}
      />
      <mesh position={[0.8, 0, 0]} scale={[1.2, 0.8, 0.8]}>
        <sphereGeometry args={[1, 8, 8]} />
        <meshBasicMaterial
          color={cloudColor}
          transparent
          opacity={0.5}
          depthWrite={false}
        />
      </mesh>
      <mesh position={[-0.8, 0, 0]} scale={[0.9, 0.9, 0.9]}>
        <sphereGeometry args={[1, 8, 8]} />
        <meshBasicMaterial
          color={cloudColor}
          transparent
          opacity={0.5}
          depthWrite={false}
        />
      </mesh>
    </mesh>
  );
}

